// Builds the real previews the library mock shows: two arXiv papers as downloaded PDFs, Wikimedia
// Commons featured photos as downloaded images, public pages the chat opened, repo plans rendered
// as pages, two of the app's UI check captures, and a sample deck. Run from the repo root with
// `node docs/mockups/assets/library/build-assets.mjs`; it needs network, Playwright's Chromium,
// pdftoppm and ImageMagick. Nothing here is generated by a model; every pixel is a render.

import { chromium } from 'playwright'
import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs'
import { join } from 'node:path'
import { micromark } from 'micromark'
import { gfm, gfmHtml } from 'micromark-extension-gfm'

const out = 'docs/mockups/assets/library'
const raw = join(out, 'raw')
mkdirSync(raw, { recursive: true })

// The plan the viewer opens, as its real source and rendered preview. `--content-only` rebuilds
// just this, after the plan changes.
const planFile = 'docs/research/document-library-viewer-options.md'
const planSource = readFileSync(planFile, 'utf8')
writeFileSync(join(out, 'content.js'), `window.PLAN = ${JSON.stringify({
  path: planFile,
  source: planSource,
  html: micromark(planSource, { extensions: [gfm()], htmlExtensions: [gfmHtml()] }),
})}\n`)
if (process.argv.includes('--content-only')) process.exit(0)

// Cookie banners and sticky chat bubbles would sit on top of every capture.
const hideOverlays = `
  [id*="onetrust"], [class*="cookie"], [id*="cookie"], [class*="consent"], [id*="consent"],
  [class*="Cookie"], [aria-label*="cookie" i], iframe[title*="chat" i], #drift-widget,
  [class*="intercom"] { display: none !important; }`

const pages = [
  { id: 'ranch', url: 'https://www.ranch.inc/', shot: true },
  { id: 'llmbook', url: 'https://llmbook.icsgen-ai.org/part-6-agentic-ai/module-29-specialized-agents/section-29.2.html', shot: true, pdf: true },
]

const papers = { react: 'https://arxiv.org/pdf/2210.03629', sweagent: 'https://arxiv.org/pdf/2405.15793' }

// Featured pictures, so the grid has photographs the way a real downloads folder does.
const photos = [
  'Kimono Forest at night, Arashiyama Station, Arashiyama, Kyoto, Japan.jpg',
  'Myeongjeongjeon seen through the wooden Gate Hyehwamun at Changgyeonggung Palace in Seoul.jpg',
  'Piazzetta San Marco Venice BLS.jpg',
  'Cloud Forest, Gardens by the Bay, Singapore.jpg',
  '2018 01 (Blue) - Chaouen.jpg',
  '2015 Ribblehead Viaduct 1.jpg',
  'A Late evening view to Austnesfjorden at Sildpollnes Church, Austvågøya, Lofoten, Norway, 2015 April.jpg',
  'Mount Fuji from Lake Kawaguchi.jpg',
  'Golden Gate Bridge as seen from Battery East.jpg',
  'Antwerp Central Station full size.jpg',
]

async function download(url, path) {
  const res = await fetch(url, { headers: { 'User-Agent': 'RocketMock/1.0 (personal mockup build)' } })
  if (!res.ok) throw new Error(`${url} answered ${res.status}`)
  writeFileSync(path, Buffer.from(await res.arrayBuffer()))
}

for (const [id, url] of Object.entries(papers)) await download(url, join(raw, `${id}.pdf`))
for (const [i, name] of photos.entries()) {
  await download(`https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(name.replaceAll(' ', '_'))}?width=1600`, join(raw, `photo-${i + 1}.jpg`))
}

const docs = [
  { id: 'doc-library-options', file: 'docs/research/document-library-viewer-options.md' },
  { id: 'sources-plan', file: 'docs/sources-plan.md' },
  { id: 'goals-phase1', file: 'docs/goals-phase1.md' },
  { id: 'attachments-roadmap', file: 'docs/attachments-roadmap.md' },
]

const pageCss = `
  @page { size: Letter; margin: 0 }
  body { margin: 0; background: #fff; color: #1d1d1f; font: 14px/1.55 Inter, system-ui, sans-serif; }
  article { padding: 64px 72px; }
  h1 { font-size: 26px; line-height: 1.2; margin: 0 0 18px; letter-spacing: -0.01em; }
  h2 { font-size: 18px; margin: 26px 0 10px; } h3 { font-size: 15px; margin: 20px 0 8px; }
  p, li { color: #333; } a { color: #4b48d6; text-decoration: none; }
  code { font: 12.5px 'Geist Mono', ui-monospace, monospace; background: #f1f1f4; padding: 1px 4px; border-radius: 4px; }
  pre { background: #f5f5f7; padding: 12px 14px; border-radius: 8px; overflow: hidden; }
  table { border-collapse: collapse; width: 100%; font-size: 12.5px; margin: 12px 0; }
  th, td { border: 1px solid #e3e3e8; padding: 6px 8px; text-align: left; vertical-align: top; }
  th { background: #f6f6f8; }`

const slides = [
  `<div class="s s1"><small>Board meeting · Q3 2026</small><h1>Q3 review</h1><p>Growth, retention and the year ahead</p></div>`,
]
const slideCss = `
  body { margin: 0; } .s { width: 1600px; height: 900px; box-sizing: border-box; padding: 110px 120px;
    font-family: Inter, system-ui, sans-serif; position: relative; overflow: hidden; }
  .s small { font-size: 26px; letter-spacing: .12em; text-transform: uppercase; opacity: .7 }
  .s1 { background: radial-gradient(1200px 700px at 85% 110%, #ff7a45 0, #c2185b 38%, #2a0f3d 75%); color: #fff }
  .s1 h1 { font-size: 150px; margin: 240px 0 10px; letter-spacing: -0.04em } .s1 p { font-size: 40px; opacity: .85; margin: 0 }
  .s2 { background: #fbf7f2; color: #1b1b1f } .s2 h2, .s3 h2 { font-size: 84px; margin: 30px 0 0; letter-spacing: -0.03em }
  .bars { position: absolute; left: 120px; right: 120px; bottom: 110px; height: 420px; display: flex; align-items: flex-end; gap: 40px }
  .bars i { flex: 1; background: linear-gradient(#ff7a45, #c2185b); border-radius: 10px 10px 0 0 }
  .s3 { background: #12131a; color: #fff } .s3 ol { font-size: 54px; line-height: 1.7; margin-top: 70px }`

// Any installed Chrome will do; Playwright's own build may not be downloaded.
const browser = await chromium.launch({ executablePath: process.env.CHROME ?? '/usr/bin/google-chrome' })
const context = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 })

for (const p of pages) {
  const page = await context.newPage()
  await page.goto(p.url, { waitUntil: 'networkidle', timeout: 60000 }).catch(() => {})
  await page.waitForTimeout(3000)
  await page.addStyleTag({ content: hideOverlays }).catch(() => {})
  await page.waitForTimeout(500)
  if (p.shot) await page.screenshot({ path: join(raw, `${p.id}.png`) })
  if (p.pdf) {
    await page.emulateMedia({ media: 'print' })
    await page.pdf({ path: join(raw, `${p.id}.pdf`), format: 'Letter', printBackground: true })
  }
  await page.close()
}

for (const d of docs) {
  const html = micromark(readFileSync(d.file, 'utf8'), { extensions: [gfm()], htmlExtensions: [gfmHtml()] })
  const page = await context.newPage()
  await page.setContent(`<style>${pageCss}</style><article>${html}</article>`)
  await page.pdf({ path: join(raw, `${d.id}.pdf`), format: 'Letter', printBackground: true })
  await page.close()
}

{
  const page = await context.newPage()
  await page.setViewportSize({ width: 1600, height: 900 })
  for (const [i, s] of slides.entries()) {
    await page.setContent(`<style>${slideCss}</style>${s}`)
    await page.screenshot({ path: join(raw, `deck-${i + 1}.png`) })
  }
  await page.close()
}

await browser.close()

const run = (cmd, args) => execFileSync(cmd, args, { stdio: 'inherit' })

// Document pages: the first pages at viewer size and a smaller copy for the grid.
for (const id of ['react', 'sweagent', 'llmbook', ...docs.map(d => d.id)]) {
  // One page per call with -singlefile, since pdftoppm pads page numbers to the page count.
  for (const n of [1, 2, 3]) {
    run('pdftoppm', ['-hide-annotations', '-r', '120', '-f', `${n}`, '-l', `${n}`, '-singlefile', '-jpeg', '-jpegopt', 'quality=80', join(raw, `${id}.pdf`), join(out, `${id}-p${n}`)])
  }
  run('convert', [join(out, `${id}-p1.jpg`), '-resize', '420x', '-quality', '84', join(out, `${id}-thumb.jpg`)])
}

// Word boxes for the agent highlight on the ReAct paper, so marks sit on real text.
run('pdftotext', ['-f', '1', '-l', '1', '-bbox', join(raw, 'react.pdf'), join(raw, 'react-bbox.html')])

// Captures and the deck: full size for the viewer, a cover crop for the grid.
const captures = ['ranch.png', 'deck-1.png', ...photos.map((_, i) => `photo-${i + 1}.jpg`)]
for (const file of captures) {
  const id = file.replace(/\.\w+$/, '')
  const gravity = id.startsWith('photo') ? 'center' : 'north'
  run('convert', [join(raw, file), '-resize', '1400x', '-quality', '80', join(out, `${id}.jpg`)])
  run('convert', [join(raw, file), '-resize', '560x350^', '-gravity', gravity, '-extent', '560x350', '-quality', '84', join(out, `${id}-shot.jpg`)])
}

// Two of the app's own UI check captures, standing in for screenshots a chat attached.
const appShots = {
  'app-plan': '.artifacts/ui/2026-10-06T03-38-55-158Z-x7nRDF/results/plan-a-plan-opens-beside-t-491a7--and-remembers-being-closed/plan-open-window.png',
  'app-changes': '.artifacts/ui/2026-10-06T02-17-31-164Z-VWL2ST/results/changes-a-turn-s-changes-s-c716a-ns-the-diff-beside-the-chat/changes-panel-window.png',
}
for (const [id, file] of Object.entries(appShots)) {
  run('convert', [file, '-resize', '1440x', '-quality', '86', join(out, `${id}.jpg`)])
  run('convert', [file, '-resize', '560x350^', '-gravity', 'center', '-extent', '560x350', '-quality', '84', join(out, `${id}-shot.jpg`)])
}

// The user's reference screenshot, kept at its own pixels (it is only 259px wide).
run('convert', ['/home/dp/.config/Rocket/attachments/d57863b2-11d7-4a83-b9cb-9c9d695d0a50.png', '-quality', '90', join(out, 'ranch-reference.jpg')])

writeFileSync(join(out, 'README.md'), [
  'Previews for `../../document-library.html`, rebuilt by `build-assets.mjs`. `raw/` is not kept.',
  '',
  'Papers: arXiv 2210.03629 (ReAct) and 2405.15793 (SWE-agent). Photos: Wikimedia Commons featured pictures,',
  'each under its own licence on its Commons page:',
  ...photos.map((name, i) => `- photo-${i + 1}: https://commons.wikimedia.org/wiki/File:${encodeURIComponent(name.replaceAll(' ', '_'))}`),
  '',
].join('\n'))
if (!process.env.KEEP_RAW) rmSync(raw, { recursive: true, force: true })
